-- Catálogo de productos de la versión DH.
--
-- Generado por tools/importar_catalogo_excel.py (repo del POS) desde
-- Productos - Todos los Productos_20261121.xlsx. 1993 productos. No editar a mano: regenerar.
--
-- Mismos ids (UUIDv5 del código) que el seed de SQLite de la app. Re-ejecutable:
-- UPSERT que no toca stock_mil, que es del kardex (ver db/README.md del POS).

ON CONFLICT (id) DO UPDATE SET
    clave_interna = excluded.clave_interna,
    nombre = excluded.nombre,
    precio_venta_cent = excluded.precio_venta_cent,
    costo_cent = excluded.costo_cent,
    unidad_medida = excluded.unidad_medida,
    clave_prod_serv = excluded.clave_prod_serv,
    clave_unidad = excluded.clave_unidad,
    permite_decimales = excluded.permite_decimales,
    activo = excluded.activo;
